const listContentHealthFindings = `-- name: ListContentHealthFindings :many


SELECT f.signal, f.ord, f.source_id, s.name AS source_name, s.type::text AS source_type, f.document_id, f.ref, f.group_no, f.group_size, f.code,
       f.detail, f.value, f.observed_at, f.confirmed_at, f.in_kb,
       coalesce(d.title, '')::text AS title, coalesce(d.filename, '')::text AS filename, coalesce(d.url, '')::text AS doc_url,
       coalesce(d.kind, '')::text AS kind, coalesce(d.updated_at > r.as_of, false)::bool AS changed_since
FROM content_health_findings f
JOIN content_health_reports r ON r.id = f.report_id AND r.team_id = f.team_id
JOIN data_sources s ON s.id = f.source_id AND s.team_id = f.team_id
LEFT JOIN documents d ON d.id = f.document_id AND d.source_id = f.source_id AND d.team_id = f.team_id
WHERE f.report_id = $1 AND f.team_id = $2 AND f.signal = $3 AND f.ord > $4::int
  AND (f.document_id IS NULL OR d.id IS NOT NULL)
ORDER BY f.ord
LIMIT $5
`

type ListContentHealthFindingsParams struct {
	ReportID uuid.UUID
	TeamID   uuid.UUID
	Signal   string
	AfterOrd int32
	PageSize int32
}

type ListContentHealthFindingsRow struct {
	Signal       string
	Ord          int32
	SourceID     uuid.UUID
	SourceName   string
	SourceType   string
	DocumentID   uuid.NullUUID
	Ref          string
	GroupNo      int32
	GroupSize    int32
	Code         string
	Detail       string
	Value        int64
	ObservedAt   *time.Time
	ConfirmedAt  *time.Time
	InKb         bool
	Title        string
	Filename     string
	DocUrl       string
	Kind         string
	ChangedSince bool
}

// Findings are inserted by internal/contenthealth (multi-array unnest, which sqlc cannot analyse).
// ---- what a reader sees ----------------------------------------------------------------------
// A page of findings, joined to the team's live sources and documents: one whose document or source is gone
// (or is not this team's) is not returned. Names are read now, never from the snapshot.
func (q *Queries) ListContentHealthFindings(ctx context.Context, arg ListContentHealthFindingsParams) ([]ListContentHealthFindingsRow, error) {
	rows, err := q.db.Query(ctx, listContentHealthFindings,
		arg.ReportID,
		arg.TeamID,
		arg.Signal,
		arg.AfterOrd,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListContentHealthFindingsRow{}
	for rows.Next() {
		var i ListContentHealthFindingsRow
		if err := rows.Scan(
			&i.Signal,
			&i.Ord,
			&i.SourceID,
			&i.SourceName,
			&i.SourceType,
			&i.DocumentID,
			&i.Ref,
			&i.GroupNo,
			&i.GroupSize,
			&i.Code,
			&i.Detail,
			&i.Value,
			&i.ObservedAt,
			&i.ConfirmedAt,
			&i.InKb,
			&i.Title,
			&i.Filename,
			&i.DocUrl,
			&i.Kind,
			&i.ChangedSince,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

