const pruneContentHealthReports = `-- name: PruneContentHealthReports :execrows
DELETE FROM content_health_reports r
WHERE r.status NOT IN ('queued', 'running')
  AND ($1::uuid IS NULL OR r.team_id = $1::uuid)
  AND (r.expires_at <= now()
       OR r.id IN (SELECT x.id FROM (SELECT id, row_number() OVER (PARTITION BY team_id ORDER BY created_at DESC, id DESC) AS n
                                     FROM content_health_reports
                                     WHERE $1::uuid IS NULL OR team_id = $1::uuid) x
                   WHERE x.n > $2::int))
`

type PruneContentHealthReportsParams struct {
	TeamID uuid.NullUUID
	Keep   int32
}

// Expired reports, and every report beyond a team's newest @keep (findings and coverage go with them): all teams'
// (the hourly job) or one team's (when it makes a report).
func (q *Queries) PruneContentHealthReports(ctx context.Context, arg PruneContentHealthReportsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneContentHealthReports, arg.TeamID, arg.Keep)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

